// R-DB-01: UUIDv7 text ids, sortable and opaque, generated by the app.
// No dependency: a monotonic millisecond prefix plus a 12-bit sequence keeps
// ids generated in the same millisecond strictly ordered.

const MAX_SEQUENCE = 0xfff;

let lastMs = 0;
let sequence = 0;

export function uuidv7(now: number = Date.now()): string {
  let ms = Math.floor(now);
  if (ms <= lastMs) {
    ms = lastMs;
    sequence += 1;
    if (sequence > MAX_SEQUENCE) {
      ms = lastMs + 1;
      lastMs = ms;
      sequence = 0;
    }
  } else {
    lastMs = ms;
    sequence = Math.floor(Math.random() * (MAX_SEQUENCE + 1));
  }

  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);

  let rest = ms;
  for (let i = 5; i >= 0; i -= 1) {
    bytes[i] = rest % 256;
    rest = Math.floor(rest / 256);
  }
  bytes[6] = 0x70 | ((sequence >> 8) & 0x0f);
  bytes[7] = sequence & 0xff;
  bytes[8] = 0x80 | (bytes[8]! & 0x3f);

  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** The UTC millisecond encoded in a UUIDv7, or null for another format. */
export function uuidv7Timestamp(id: string): number | null {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    return null;
  }
  return Number.parseInt(id.slice(0, 8) + id.slice(9, 13), 16);
}
